            .molongui-ui-tab-label:hover {
                background: #e1e1e1;
            }

            .molongui-ui-tab-radio:checked + .molongui-ui-tabs-navigation .molongui-ui-tab-label {
                background: #ffffff;
                border-bottom: none;
