                padding: 1em;
                background: #ffffff;
            }

            .molongui-ui-tab-content {
                display: none;
            }

            .molongui-ui-tab-radio:checked ~ .molongui-ui-tabs-content #content-tab-0,
            .molongui-ui-tab-radio:checked ~ .molongui-ui-tabs-content #content-tab-1,
